/bin/bash -lc "node --input-type=module <<'EOF'
const cases = [
  ['/products/lamp', 'Brass lamp', 'USD 120.00', 'Stone vase'],
  ['/products/lamp?currency=EUR', 'Brass lamp', 'EUR 110.40', 'Stone vase'],
  ['/products/vase', 'Stone vase', 'USD 80.00', 'Brass lamp'],
  ['/products/vase?currency=EUR', 'Stone vase', 'EUR 73.60', 'Brass lamp'],
]
for (const [path, name, price, related] of cases) {
  const response = await fetch("'`http://localhost:3100${path}`)
  const reader = response.body.getReader()
  const decoder = new TextDecoder()
  let html = '"''
  let first = null
  let details = null
  let recommendations = null
  const start = performance.now()
  while (true) {
    const { done, value } = await reader.read()
    if (done) break
    html += decoder.decode(value, { stream: true })
    const elapsed = Math.round(performance.now() - start)
    if (first === null) first = elapsed
    if (details === null && html.includes("'`<h1>${name}</h1>`) && html.includes(price)) details = elapsed
    if (recommendations === null && html.includes(`<p>${related}</p>`)) recommendations = elapsed
  }
  const valid = response.status === 200 && html.includes(`<h1>${name}</h1>`) && html.includes(price) && html.includes(`<p>${related}</p>`)
  console.log(JSON.stringify({ path, status: response.status, valid, first, details, recommendations, shell: html.includes('"'Signal Shop collection') && html.includes('Loading product details...'), relatedFallback: html.includes('Loading related products...') }))
}
const missing = await fetch('http://localhost:3100/products/missing')
console.log(JSON.stringify({ path: '/products/missing', status: missing.status }))
EOF"

/bin/bash -lc "node --input-type=module <<'EOF'
for (const suffix of ['&check=one', '&check=two']) {
  const start = performance.now()
  const response = await fetch("'`http://localhost:3100/products/lamp?currency=EUR${suffix}`)
  const reader = response.body.getReader()
  let html = '"''
  let detailAt = null
  while (true) {
    const { done, value } = await reader.read()
    if (done) break
    html += new TextDecoder().decode(value)
    if (detailAt === null && html.includes('<h1>Brass lamp</h1>')) detailAt = Math.round(performance.now() - start)
  }
  console.log(JSON.stringify({ suffix, status: response.status, detailAt, valid: html.includes('EUR 110.40') }))
}
EOF"
